@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Velour Glass - luxury dark UI authored from the Fey dark-mode reference.
 *
 * The language extracted from the screenshot:
 *   - A near-black canvas with a faint cool violet cast; panels barely lift
 *     off it (dim, focused, no glare).
 *   - Velvet surfaces: opaque vertical gradients that run dark-to-darker
 *     (top edge catches the light, bottom falls away). No backdrop blur
 *     anywhere; the material is velvet, not frosted glass.
 *   - Every raised surface wears a 0.0625rem inset light rim on its top edge and
 *     sits in a deep, soft ambient drop shadow.
 *   - The "Gold"/"Dawn" gradient swatches set the accent: a pale champagne
 *     ivory used sparingly on primary actions, light-on-dark like the
 *     reference CTA, with dark text riding on it.
 *   - Command-palette elegance: hairline separators, quiet muted labels,
 *     small raised key chips, generous radii (0.625-1rem).
 */

:root {
  /* Surfaces (elevation = slightly lighter, always velvet-dim) */
  --background: oklch(0.16 0.008 285);
  --foreground: oklch(0.95 0.006 80);

  --card: oklch(0.205 0.011 285);
  --card-foreground: oklch(0.95 0.006 80);

  --popover: oklch(0.235 0.012 285);
  --popover-foreground: oklch(0.95 0.006 80);

  /* Primary: pale champagne ivory (the Gold/Dawn swatch highlight) */
  --primary: oklch(0.905 0.035 90);
  --primary-foreground: oklch(0.2 0.012 285);

  --secondary: oklch(0.26 0.012 285);
  --secondary-foreground: oklch(0.88 0.01 285);

  --muted: oklch(0.23 0.01 285);
  --muted-foreground: oklch(0.64 0.014 285);

  --accent: oklch(0.29 0.014 285);
  --accent-foreground: oklch(0.96 0.006 80);

  --destructive: oklch(0.6 0.19 25);
  --destructive-foreground: oklch(0.98 0.008 20);

  --border: oklch(1 0 0 / 0.08);
  --input: oklch(0.135 0.008 285);  /* recessed wells sink below the canvas */
  --ring: oklch(0.86 0.05 90);
  --radius: 0.625rem;               /* 0.625rem controls; cards round up to xl */

  /*
   * Velvet gradients - all opaque, all vertical, dark-to-darker.
   * --velour:        resting card face
   * --velour-raised: raised control face (secondary buttons, chips, thumbs)
   * --velour-hover:  the raised face catching a little more light
   * --champagne:     primary fill (pale ivory gradient, dark text)
   */
  --velour: linear-gradient(
    to bottom,
    oklch(0.235 0.013 285),
    oklch(0.185 0.01 285)
  );
  --velour-raised: linear-gradient(
    to bottom,
    oklch(0.305 0.014 286),
    oklch(0.245 0.012 286)
  );
  --velour-hover: linear-gradient(
    to bottom,
    oklch(0.335 0.015 286),
    oklch(0.27 0.013 286)
  );
  --champagne: linear-gradient(
    to bottom,
    oklch(0.95 0.03 95),
    oklch(0.875 0.045 88)
  );
  --champagne-hover: linear-gradient(
    to bottom,
    oklch(0.97 0.028 95),
    oklch(0.9 0.043 88)
  );

  /*
   * Shadow scale - inset top light rim + contact + deep ambient drop.
   * Tiers: s (resting), m (hover/raised), l (floating popovers),
   * xl (dialogs). Recessed wells use --shadow-inset.
   */
  --shadow-s:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.07),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.45),
    0 0.125rem 0.5rem oklch(0 0 0 / 0.3);

  --shadow-m:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.09),
    0 0.125rem 0.375rem oklch(0 0 0 / 0.5),
    0 0.625rem 1.75rem oklch(0 0 0 / 0.38);

  --shadow-l:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.1),
    0 0 0 0.0625rem oklch(1 0 0 / 0.05),
    0 1rem 3rem oklch(0 0 0 / 0.55),
    0 0.25rem 0.75rem oklch(0 0 0 / 0.4);

  --shadow-xl:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.12),
    0 0 0 0.0625rem oklch(1 0 0 / 0.06),
    0 2rem 5rem oklch(0 0 0 / 0.65),
    0 0.5rem 1.5rem oklch(0 0 0 / 0.45);

  /* Recessed wells: form fields, tracks, the command-palette input strip. */
  --shadow-inset:
    inset 0 0.0625rem 0.1875rem oklch(0 0 0 / 0.5),
    inset 0 -0.0625rem 0 oklch(1 0 0 / 0.04);

  /* Raised velvet button (secondary/default chrome). */
  --shadow-button:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.09),
    inset 0 -0.0625rem 0.0625rem oklch(0 0 0 / 0.35),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.5),
    0 0.25rem 0.75rem oklch(0 0 0 / 0.3);

  --shadow-button-hover:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.12),
    inset 0 -0.0625rem 0.0625rem oklch(0 0 0 / 0.35),
    0 0.125rem 0.25rem oklch(0 0 0 / 0.5),
    0 0.5rem 1.375rem oklch(0 0 0 / 0.4);

  /* The champagne primary pill: bright inset top rim, warm lower bloom,
     deep ambient drop. Filled controls reuse this stack scaled down. */
  --shadow-primary:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.85),
    inset 0 -0.125rem 0.25rem oklch(0.75 0.06 85 / 0.55),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.5),
    0 0.375rem 1.125rem oklch(0 0 0 / 0.45);

  /* Chart palette: tonal ramp of the DS primary (one hue, five shades) */
  --chart-1: var(--primary);
  --chart-2: oklch(from var(--primary) calc(l - 0.09) calc(c * 0.92) h);
  --chart-3: oklch(from var(--primary) calc(l - 0.18) calc(c * 0.84) h);
  --chart-4: oklch(from var(--primary) calc(l - 0.27) calc(c * 0.76) h);
  --chart-5: oklch(from var(--primary) calc(l - 0.36) calc(c * 0.68) h);

  /* --- Motion (soft profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 180ms;
  --transition-duration-base: 240ms;
  --transition-duration-slow: 300ms;
  --ease-out: cubic-bezier(0.19, 1, 0.22, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-in: cubic-bezier(0.895, 0.03, 0.685, 0.22);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 0.125rem);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 0.125rem);
  --radius-xl: calc(var(--radius) + 0.375rem);

  --shadow-s: var(--shadow-s);
  --shadow-m: var(--shadow-m);
  --shadow-l: var(--shadow-l);
  --shadow-xl: var(--shadow-xl);
  --shadow-inset: var(--shadow-inset);
  --shadow-button: var(--shadow-button);
  --shadow-button-hover: var(--shadow-button-hover);
  --shadow-primary: var(--shadow-primary);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    letter-spacing: -0.01em;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  textarea {
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: spacious;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 62);
  --layout-inset: calc(var(--spacing, 0.25rem) * 10);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 12);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 6);
}

